import { clientsClaim } from "workbox-core";
import { cleanupOutdatedCaches, precacheAndRoute } from "workbox-precaching";
import { NavigationRoute, registerRoute } from "workbox-routing";
import { createHandlerBoundToURL } from "workbox-precaching";

// Ensures the new service worker takes control immediately.
self.skipWaiting();
clientsClaim();

// Precache all build assets generated by Vite.
precacheAndRoute(self.__WB_MANIFEST);

// Clean up old precached versions when the service worker updates.
cleanupOutdatedCaches();

// Offline app shell: serve index.html for navigation requests.
const handler = createHandlerBoundToURL("index.html");
const navigationRoute = new NavigationRoute(handler, {
  allowlist: [/^\/$/],
});

registerRoute(navigationRoute);

// Open/focus the app when a reminder notification is clicked.
self.addEventListener("notificationclick", (event) => {
  const { notification } = event;

  notification.close();

  const url = event.notification.data?.url || "/";

  event.waitUntil(
    self.clients
      .matchAll({
        type: "window",
        includeUncontrolled: true,
      })
      .then((windowClients) => {
        const existingClient = windowClients.find(
          (client) => client.url.includes(self.registration.scope) 
        );

        if (existingClient) {
          return existingClient.focus().then(() => {
            if ("navigate" in existingClient) {
              return existingClient.navigate(url);
            }
          });
        }

        return self.clients.openWindow(url);
      })
  );
});